"""Read independent source exports without using metadata as business facts."""

import hashlib
import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Iterable

from .providers import Provider


class InputError(ValueError):
    """An export or batch cannot be interpreted unambiguously."""


@dataclass(frozen=True)
class SourceDocument:
    document_id: str
    source_sha256: str
    source_bytes: bytes
    message: str


@dataclass(frozen=True)
class InputResult:
    document_id: str
    source_sha256: str
    message: str | None
    response: dict[str, Any] | None
    error: dict[str, str] | None


def decode_export(path: Path, raw: bytes) -> SourceDocument:
    """Preserve original-byte identity; expose only the decoded message."""
    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as error:
        raise InputError(
            f"{path.name}: invalid UTF-8 at byte {error.start}; re-export as UTF-8"
        ) from error
    try:
        export = json.loads(text)
    except json.JSONDecodeError as error:
        raise InputError(
            f"{path.name}: invalid JSON at line {error.lineno}, column {error.colno}; "
            "supply a valid JSON export"
        ) from error
    if not isinstance(export, dict):
        raise InputError(f"{path.name}: export must be a JSON object containing a message string")
    if not isinstance(export.get("message"), str):
        raise InputError(f"{path.name}: message is missing or is not a string; supply message text")
    return SourceDocument(
        document_id=path.name,
        source_sha256=hashlib.sha256(raw).hexdigest(),
        source_bytes=raw,
        message=export["message"],
    )


def process_exports(paths: Iterable[Path], *, provider: Provider) -> list[InputResult]:
    """Reject batch identity collisions before calls, then process each export.

    Malformed source data becomes a per-document error. Provider envelopes are
    returned unchanged for validation by the next stage.
    """
    batch = [Path(path) for path in paths]
    seen: set[str] = set()
    for path in batch:
        if path.name in seen:
            raise InputError(f"Duplicate basename {path.name}; use distinct filenames in a batch")
        seen.add(path.name)

    results = []
    for path in batch:
        raw = path.read_bytes()
        try:
            document = decode_export(path, raw)
        except InputError as error:
            results.append(InputResult(
                document_id=path.name,
                source_sha256=hashlib.sha256(raw).hexdigest(),
                message=None,
                response=None,
                error={"code": "input-error", "message": str(error)},
            ))
            continue
        results.append(InputResult(
            document_id=document.document_id,
            source_sha256=document.source_sha256,
            message=document.message,
            response=provider.extract(document.message),
            error=None,
        ))
    return results

"""Offline test harness; all provider replies come from saved fixtures."""

import json
import os
import socket
import unittest
from pathlib import Path
from unittest.mock import patch

from access_intake.providers import MockOutcome, MockProvider

ROOT = Path(__file__).resolve().parents[1]
MOCKS = ROOT / "tests" / "mock_responses"
REQUESTS = ROOT / "materials" / "requests"


def saved(name):
    return json.loads((MOCKS / f"{name}.json").read_text(encoding="utf-8"))


def message(name="IT-001.json"):
    return json.loads((REQUESTS / name).read_text(encoding="utf-8"))["message"]


def playback(*names):
    return MockProvider([MockOutcome(response_path=MOCKS / f"{name}.json") for name in names])


class OfflineTest(unittest.TestCase):
    def setUp(self):
        original = type(os.environ).__getitem__

        def guard(environ, key):
            if key == "API_KEY":
                raise AssertionError("Test must not read API_KEY")
            return original(environ, key)

        self.key_guard = patch.object(type(os.environ), "__getitem__", guard)
        self.key_guard.start()
        self.addCleanup(self.key_guard.stop)
        for name in ("socket", "create_connection", "getaddrinfo"):
            patcher = patch.object(socket, name, side_effect=AssertionError("Network denied in tests"))
            patcher.start()
            self.addCleanup(patcher.stop)

    def assert_error(self, record, code):
        self.assertIsNone(record["extraction"])
        self.assertEqual((record["status"], record["owner"], record["next_action"]),
                         ("error", "IT Service Desk", "retry-extraction"))
        self.assertEqual(record["error"]["code"], code)
        self.assertTrue(record["error"]["message"])

