            command.add_argument("--provider", choices=("mock", "live"), default="mock")
            command.add_argument("--mock-map", type=Path)
            command.add_argument("--policy-version")
            command.add_argument("--prompt-file", type=Path)
        if name == "intake":
            command.add_argument("paths", nargs="+", type=Path)
        if name in ("intake", "retry", "resume", "refresh"):
            command.add_argument("--workers", type=int, default=4)
            command.add_argument("--timeout", type=float, default=60)
            command.add_argument("--max-calls", type=int, default=3)
            command.add_argument("--enqueue-only", action="store_true")
        if name in ("queue", "progress", "history"):
            command.add_argument("--limit", type=int, default=100)
            command.add_argument("--offset", type=int, default=0)
        if name == "history":
            command.add_argument("--document", required=True)
        if name == "retry":
            command.add_argument("--attempt", required=True)
        if name == "export":
            command.add_argument("--out", type=Path, required=True)
            command.add_argument("--copy-to", type=Path)
    return parser


def _settings(args):
    if args.provider == "live":
        from .http_provider import HttpProvider
        settings = ProcessingSettings.from_provider(HttpProvider.from_environment())
    else:
        settings = ProcessingSettings()
    if args.policy_version:
        settings = replace(settings, policy_version=args.policy_version)
    if args.prompt_file:
        settings = replace(settings, prompt=args.prompt_file.read_text(encoding="utf-8"))
    return settings


def main(argv=None, *, provider_factory=None, hook=None, scheduler_options=None):
    args = _parser().parse_args(argv)
    try:
        if hasattr(args, "limit") and (not 1 <= args.limit <= 10000 or args.offset < 0):
            raise ValueError("Use a limit from 1 to 10000 and a nonnegative offset")
        with Repository(args.state) as repo:
            if args.command == "queue":
                result = repo.queue_page(limit=args.limit, offset=args.offset)
            elif args.command == "progress":
                result = repo.progress_page(limit=args.limit, offset=args.offset)
            elif args.command == "history":
                records = repo.history(args.document)
                result = {"total": len(records), "items": records[args.offset:args.offset + args.limit]}
            elif args.command == "export":
                from .snapshots import export_generation, read_snapshot
                manifest = export_generation(repo, args.out)
                if args.copy_to:
                    snapshot = read_snapshot(args.out)
                    args.copy_to.mkdir(parents=True, exist_ok=True)
                    # Copy only the generation resolved and verified above.
                    (args.copy_to / "extractions.jsonl").write_text("".join(json.dumps(r, ensure_ascii=False) + "\n" for r in snapshot["extractions"]), encoding="utf-8")
                    (args.copy_to / "queue.json").write_text(json.dumps(snapshot["queue"], ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
                result = manifest
            else:
                if args.command == "intake":
                    paths = batch_paths(p for path in args.paths for p in (sorted(path.glob("*.json")) if path.is_dir() else [path]))
                    settings = _settings(args)
                    for path in paths:
                        raw = path.read_bytes()
                        producing = settings_for_source(path, raw, args.mock_map or Path("config/mock-map.json"), settings) if args.provider == "mock" else settings
                        repo._schedule(path.name, raw, producing)
                elif args.command == "retry":
                    repo.enqueue_retry(args.attempt)
                elif args.command == "refresh":
                    settings = _settings(args)
                    rows = repo.connection.execute("SELECT a.* FROM documents d JOIN attempts a ON a.attempt_id=d.latest_attempt_id").fetchall()
                    for row in rows:
                        producing = settings
                        if args.provider == "mock":
                            producing = (settings_for_source(row["document_id"], row["source_bytes"], args.mock_map, settings)
                                         if args.mock_map else replace(settings, request_settings=json.loads(row["settings_json"])["request_settings"]))
                        repo._schedule(row["document_id"], row["source_bytes"], producing)
                metrics = {} if args.enqueue_only else Scheduler(repo, provider_factory=provider_factory or provider_for_settings,
                    workers=args.workers, timeout=args.timeout, max_calls=args.max_calls, hook=hook,
                    **(scheduler_options or {})).run()
                result = {"scheduler": metrics, "progress": repo.progress_page(limit=20)}
        print(json.dumps(result, ensure_ascii=False))
        return 0
    except KeyboardInterrupt:
        return 130
    except (ValueError, OSError, KeyError) as error:
        print(json.dumps({"error": str(error)}), file=sys.stderr)
        return 2

"""Explicit saved-response configuration for reproducible offline CLI runs."""

import hashlib
import json
from dataclasses import replace
from pathlib import Path

from .inputs import InputError, decode_export
from .providers import ProviderUnavailable


def settings_for_source(path, raw, manifest_path, settings):
    try:
        document = decode_export(Path(path), raw)
    except InputError:
        return settings
    manifest_path = Path(manifest_path)
    manifest = json.loads(manifest_path.read_text())
    identity = hashlib.sha256(document.message.encode("utf-8")).hexdigest()
    entry = manifest.get(identity)
    if entry is None:
        return replace(settings, request_settings={})
    fixture = (manifest_path.parent / entry["response"]).resolve()
    configuration = {"path": str(fixture), "sha256": hashlib.sha256(fixture.read_bytes()).hexdigest(),
                     "substitutions": entry.get("substitutions", {})}
    return replace(settings, request_settings={"mock_response": configuration})


class SavedProvider:
    def __init__(self, settings):
        self.settings = settings

    def extract(self, message):
        entry = self.settings.request_settings.get("mock_response")
        if entry is None:
            raise ProviderUnavailable("No saved response configured for this message")
        raw = Path(entry["path"]).read_bytes()
        if hashlib.sha256(raw).hexdigest() != entry["sha256"]:
            raise ProviderUnavailable("Saved response changed; refresh the producing configuration")
        text = raw.decode("utf-8")
        for old, new in entry["substitutions"].items():
            text = text.replace(old, new)
        envelope = json.loads(text)
        return {**envelope, "response_source": "mock"}


def provider_for_settings(settings):
    if settings.provider == "mock":
        return SavedProvider(settings)
    from .http_provider import HttpProvider
    return HttpProvider.from_settings(settings)

"""Bounded process workers, durable backoff and hard total-attempt deadlines."""

import json
import multiprocessing
import random
import signal
import threading
from multiprocessing.connection import wait as wait_connections
from time import sleep, time

from .providers import ProviderUnavailable
from .repository import ProcessingSettings, Repository
from .validation import error_record

CTX = multiprocessing.get_context("fork")


def retry_delay(error, calls, *, jitter=random.random, base_delay=0.5):
    requested = getattr(error, "retry_after", None)
    if requested is not None:
        return min(60, max(0, requested))
    return min(10, base_delay * 2 ** (calls - 1)) * (1 + jitter() * 0.25)


def _compute(path, job, provider, sender):
    signal.signal(signal.SIGTERM, signal.SIG_DFL)
    try:
        with Repository(path) as repository:
            result = repository.compute(job, provider=provider, raise_provider_errors=True)
        sender.send(("result", result))
    except (ProviderUnavailable, TimeoutError) as error:
        sender.send(("failure", {"code": getattr(error, "code", "provider-unavailable"),
                                 "retryable": getattr(error, "retryable", True),
                                 "retry_after": getattr(error, "retry_after", None)}))
    except BaseException:
        sender.send(("failure", {"code": "worker-error", "retryable": False, "retry_after": None}))
    finally:
        sender.close()


class Scheduler:
    def __init__(self, repository, *, provider_factory, workers=4, timeout=60, max_calls=3,
                 clock=time, wait=sleep, jitter=random.random, base_delay=0.5, hook=None):
        if not 1 <= workers <= 32 or timeout <= 0 or not 1 <= max_calls <= 3:
            raise ValueError("Use 1–32 workers, a positive timeout, and 1–3 provider calls")
        self.repository = repository
        self.factory = provider_factory
        self.workers, self.timeout, self.max_calls = workers, timeout, max_calls
        self.clock, self.wait, self.jitter = clock, wait, jitter
        self.base_delay = base_delay
        self.hook = hook or (lambda stage, job: None)

    def _failure(self, job, details):
        from .http_provider import ProviderFailure
        error = ProviderFailure(details["code"], "Provider call failed", retryable=details["retryable"], retry_after=details.get("retry_after"))
        delay = retry_delay(error, job["call_count"], jitter=self.jitter, base_delay=self.base_delay)
        if error.retryable and job["call_count"] < self.max_calls and self.clock() + delay < job["deadline"]:
            self.repository.defer(job, seconds=delay)
            self.hook("retry-wait", job)
            return
        settings = ProcessingSettings(**json.loads(job["settings_json"]))
        source = "mock" if settings.provider == "mock" else f"{settings.provider}/{settings.model}"
        result = self.repository.decorate(job, error_record(error.code, "Extraction failed or timed out; retry this saved attempt", source))
        self.repository.finish(job, result)
        self.hook("completed", job)

    def run(self):
        self.repository.recover()
        active = {}
        metrics = {"max_active": 0, "calls": 0}
        old_handler = None
        if threading.current_thread() is threading.main_thread():
            old_handler = signal.getsignal(signal.SIGTERM)
            def interrupted(signum, frame):
                raise KeyboardInterrupt
            signal.signal(signal.SIGTERM, interrupted)
        try:
            while True:
                while len(active) < self.workers:
                    job = self.repository.claim(lease_seconds=self.timeout + 5)
                    if job is None:
                        break
                    job = self.repository.prepare_call(job, timeout=self.timeout)
                    if self.clock() >= job["deadline"]:
                        self._failure(job, {"code": "attempt-timeout", "retryable": False})
                        continue
                    try:
                        provider = self.factory(ProcessingSettings(**json.loads(job["settings_json"])))
                    except (ValueError, OSError, KeyError, ProviderUnavailable):
                        self._failure(job, {"code": "provider-configuration", "retryable": False})
                        continue
                    receiver, sender = CTX.Pipe(duplex=False)
                    process = CTX.Process(target=_compute, args=(self.repository.path, job, provider, sender))
                    process.start()
                    sender.close()
                    active[receiver] = (process, job)
                    metrics["calls"] += 1
                    metrics["max_active"] = max(metrics["max_active"], len(active))
                    self.hook("spawned", job)
                if not active:
                    next_run = self.repository.connection.execute("SELECT min(next_run_at) FROM attempts WHERE work_state IN ('queued','retry-wait')").fetchone()[0]
                    if next_run is None:
                        break
                    self.wait(max(0, next_run - self.clock()))
                    continue
                ready = wait_connections(list(active), timeout=0.05)
                for connection in list(active):
                    process, job = active[connection]
                    timed_out = self.clock() >= job["deadline"]
                    if connection not in ready and not timed_out:
                        continue
                    if timed_out:
                        kind, payload = "failure", {"code": "attempt-timeout", "retryable": False}
                    else:
                        try:
                            kind, payload = connection.recv()
                        except EOFError:
                            kind, payload = "failure", {"code": "worker-exited", "retryable": True}
                    if process.is_alive() and timed_out:
                        process.terminate()
                    process.join(5)
                    if process.is_alive():
                        process.kill()
                        process.join()
                    connection.close()
                    del active[connection]
                    if kind == "result":
                        self.repository.finish(job, payload)
                        self.hook("completed", job)
                    else:
                        self._failure(job, payload)
        finally:
            for connection, (process, job) in active.items():
                process.terminate()
                process.join(5)
                if process.is_alive():
                    process.kill()
                    process.join()
                connection.close()
                self.repository.interrupt(job)
            if old_handler is not None:
                signal.signal(signal.SIGTERM, old_handler)
        return metrics
